/* eslint-env serviceworker */

// Use dynamic imports to avoid module syntax issues in service workers
importScripts('https://storage.googleapis.com/workbox-cdn/releases/7.0.0/workbox-sw.js');

if (workbox) {
  const { registerRoute } = workbox.routing;
  const { StaleWhileRevalidate } = workbox.strategies;
  const { precacheAndRoute } = workbox.precaching;

  // Precache all assets generated by the build process
  precacheAndRoute(self.__WB_MANIFEST);

  // Cache requests for same-origin images
  registerRoute(
    ({ request }) => request.destination === "image",
    new StaleWhileRevalidate()
  );

  // Cache Firebase scripts for offline functionality
  registerRoute(
    ({ url }) => url.hostname === 'www.gstatic.com',
    new StaleWhileRevalidate({
      cacheName: 'firebase-scripts',
      expiration: {
        maxEntries: 10,
        maxAgeSeconds: 60 * 60 * 24 * 7 // 1 week
      }
    })
  );
}

// ---- Firebase Messaging (unified in main SW) ----
// Load Firebase compat scripts to enable messaging in the same service worker
// This allows FCM background messages to be handled here instead of a separate SW file
// Note: Keep using the compat layer for onBackgroundMessage support in SW context
importScripts('https://www.gstatic.com/firebasejs/11.0.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/11.0.1/firebase-messaging-compat.js');

try {
  // Initialize Firebase in the service worker (same config as app)
  // Using explicit values to avoid depending on import.meta in SW context
  firebase.initializeApp({
    apiKey: "AIzaSyDjk-Y3jeoPy3nW_9MniNs8heBv17briMU",
    authDomain: "studio-gpnfx.firebaseapp.com",
    projectId: "studio-gpnfx",
    storageBucket: "studio-gpnfx.firebasestorage.app",
    messagingSenderId: "848246677738",
    appId: "1:848246677738:web:7612dab5f030c52b227793"
  });

  const messaging = firebase.messaging();

  // Handle FCM background messages with enhanced mobile support
  messaging.onBackgroundMessage((payload) => {
    console.log('🔔 [SW] FCM background message received:', payload);
    
    const title = payload.notification?.title || 'Ubora';
    const body = payload.notification?.body || 'Vous avez reçu une nouvelle notification';
    const uniqueTag = `ubora-fcm-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    
    const options = {
      body: body,
      icon: '/fav-icons/android-icon-192x192.png',
      badge: '/fav-icons/android-icon-96x96.png',
      data: {
        ...payload.data,
        fcmMessageId: payload.messageId,
        timestamp: Date.now()
      },
      tag: uniqueTag,
      requireInteraction: false, // Allow auto-dismiss for better UX
      silent: false,
      vibrate: [200, 100, 200], // Vibration pattern for mobile
      actions: [
        {
          action: 'open',
          title: 'Ouvrir',
          icon: '/fav-icons/android-icon-48x48.png'
        },
        {
          action: 'dismiss',
          title: 'Ignorer',
          icon: '/fav-icons/android-icon-48x48.png'
        }
      ]
    };
    
    self.registration.showNotification(title, options);
  });
} catch (e) {
  // Fail silently if Firebase scripts are unavailable
}

// Listen for push events
self?.addEventListener("push", (event) => {
  const data = event.data?.json() ?? {};
  const title = data.title || "New Notification";
  const options = {
    body: data.body,
    icon: "/fav-icons/android-icon-192x192.png",
    data,
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

// Handle notification click with action support
self?.addEventListener("notificationclick", (event) => {
  console.log('🔔 [SW] Notification clicked:', event);
  
  event.notification.close();

  // Handle action buttons
  if (event.action === 'dismiss') {
    return;
  }

  // Determine the URL to open based on notification data
  let urlToOpen = '/';
  const notificationData = event.notification.data;
  
  if (notificationData) {
    // Handle form-related notifications
    if (notificationData.formId) {
      if (notificationData.action === 'form_assigned' || notificationData.action === 'form_created') {
        urlToOpen = '/forms';
      } else if (notificationData.action === 'form_submission') {
        urlToOpen = '/dashboard';
      } else if (notificationData.action === 'form_reminder') {
        urlToOpen = '/forms';
      }
    }
    
    // Handle other notification types
    if (notificationData.type === 'director_message') {
      urlToOpen = '/notifications';
    } else if (notificationData.type === 'system_alert') {
      urlToOpen = '/dashboard';
    } else if (notificationData.type === 'reminder') {
      urlToOpen = '/forms';
    } else if (notificationData.url) {
      urlToOpen = notificationData.url;
    }
  }

  // Open the app
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If app is already open, focus it and navigate to the specific page
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          // Send a message to the client to navigate to the specific page
          client.postMessage({
            type: 'NOTIFICATION_CLICK',
            data: notificationData,
            url: urlToOpen
          });
          return client.focus();
        }
      }
      // If app is not open, open it with the specific URL
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});

// Handle messages from the main thread (for test notifications)
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SHOW_NOTIFICATION') {
    const { payload } = event.data;
    const title = payload.notification?.title || 'Test Notification';
    const options = {
      body: payload.notification?.body,
      icon: '/fav-icons/android-icon-192x192.png',
      badge: '/fav-icons/android-icon-96x96.png',
      data: payload.data || {},
      tag: `ubora-test-${Date.now()}`,
      requireInteraction: false,
      silent: false
    };
    
    self.registration.showNotification(title, options);
  }
});
